/**
 * Plain-language effects and risks of a PreparedWrite (`explain_prepared_write`).
 *
 * Deterministic and template-based, not generated by the model: the explanation
 * the user reads next to the Approve button must come from the decoded call and
 * the simulation, so nothing a contract author wrote (names, NatSpec, revert
 * text) can reword it. On-chain strings that do appear are quoted as untrusted.
 */
import { formatEther } from "viem";
import type { PreparedWrite } from "@/lib/contracts/types";
import { unwrapUntrusted } from "./untrusted";

export interface WriteExplanation {
  summary: string;
  effects: string[];
  risks: string[];
  cost: string;
  nextStep: string;
}

function argLine(a: PreparedWrite["call"]["args"][number]): string {
  const v = typeof a.value === "string" ? unwrapUntrusted(a.value) : JSON.stringify(a.value);
  const shown = typeof a.value === "string" && a.type === "string" ? `"${v}" (text from the caller, shown as data)` : v;
  return `${a.name || "(unnamed)"} (${a.type}) = ${shown}`;
}

export function explainPreparedWrite(p: PreparedWrite): WriteExplanation {
  const who = p.target.label ?? p.target.address;
  const verified =
    p.target.verification === "verified"
      ? "a verified contract"
      : p.target.abiSource === "implementation"
        ? "a proxy whose implementation was decoded"
        : p.target.verification === "partial-match"
          ? "a partially matched (not verified) contract"
          : p.target.verification === "unavailable" && p.target.isContract
            ? "a contract whose verification status is unknown right now"
            : p.target.isContract
              ? "an unverified contract"
            : "an address with no contract code";
  const value = BigInt(p.value.wei);
  const summary =
    `Call ${p.call.function} on ${who}, ${verified}, on Citrate (chain ${p.chainId})` +
    (value > 0n ? `, sending ${formatEther(value)} SALT.` : ", sending no SALT.");

  const effects: string[] = [];
  effects.push(`Function: ${p.call.signature} (selector ${p.call.selector}).`);
  for (const a of p.call.args) effects.push(`Argument ${argLine(a)}.`);
  effects.push(
    p.simulation.ok
      ? `Simulated from ${p.simulation.from ?? "no sender"} at block ${p.simulation.blockNumber ?? "?"}: it succeeds.`
      : p.simulation.revertReason
        ? `Simulated from ${p.simulation.from ?? "no sender"}: it reverts (${unwrapUntrusted(p.simulation.revertReason)}).`
        : "The simulation could not run, so the outcome is unknown.",
  );

  const cost = p.simulation.gasEstimate
    ? `About ${p.simulation.gasEstimate} gas` + (p.simulation.feeSalt ? `, roughly ${p.simulation.feeSalt} SALT at the current price.` : ".")
    : "Gas could not be estimated.";

  const risks = p.risk.flags.map((f) => `${f.severity === "elevated" ? "High" : f.severity === "warn" ? "Note" : "Info"}: ${f.message}`);
  if (risks.length === 0) risks.push("No specific risk flags for this call.");

  const nextStep =
    "Nothing has been sent. To go ahead, open the approval dialog, check these details against what you intend, and approve; " +
    "you then sign in your own wallet" +
    (p.relay.eligible ? " or use the gasless relay." : ".") +
    (p.risk.elevated ? ` Because this call is flagged, you will be asked to type "${p.risk.confirmPhrase}" to confirm.` : "");

  return { summary, effects, risks, cost, nextStep };
}
